SELECT CASE WHEN total_lam = 0 THEN 0.0 ELSE (100.0 * above_count) / total_lam END AS percentage
FROM (
  SELECT
    (SELECT COUNT(*) FROM customers WHERE Segment = 'LAM') AS total_lam,
    (SELECT COUNT(DISTINCT y.CustomerID)
     FROM yearmonth y
     JOIN customers c ON y.CustomerID = c.CustomerID
     WHERE c.Segment = 'LAM' AND COALESCE(y.Consumption,0) > 46.73
    ) AS above_count
);

