WITH latest_per_player AS (
  SELECT pa.player_api_id, pa.overall_rating
  FROM Player_Attributes pa
  JOIN (SELECT player_api_id, MAX(date) AS maxdate FROM Player_Attributes GROUP BY player_api_id) m
    ON pa.player_api_id = m.player_api_id AND pa.date = m.maxdate
),
la AS (
  SELECT l.overall_rating AS orat FROM latest_per_player l JOIN Player p ON l.player_api_id = p.player_api_id WHERE p.player_name = 'Ariel Borysiuk'
),
lp AS (
  SELECT l.overall_rating AS orat FROM latest_per_player l JOIN Player p ON l.player_api_id = p.player_api_id WHERE p.player_name = 'Paulin Puel'
)
SELECT ((CAST((SELECT orat FROM la) AS REAL) - CAST((SELECT orat FROM lp) AS REAL)) / NULLIF(CAST((SELECT orat FROM lp) AS REAL),0)) * 100.0 AS percentage_higher;

